    try:
        car_patches, car_patches_boxes = sliding_window_detection(image_1, ["car"])
        for i, patch in enumerate(car_patches):
            print(f"Car patch {i+1} boxes:", car_patches_boxes[i])
            display(patch.annotated_image)
    except Exception as e:
        print("Sliding-window fallback for car failed with error:", e)

if not bike_boxes:
    print("\nNo bicycle boxes detected — trying sliding_window_detection for 'bicycle' as fallback...")
    try:
        bike_patches, bike_patches_boxes = sliding_window_detection(image_1, ["bicycle"])
